ruby -rselenium-webdriver -e '
  opts = Selenium::WebDriver::Chrome::Options.new
  opts.add_argument("--headless")
  opts.add_argument("--no-sandbox")
  driver = Selenium::WebDriver.for(:chrome, options: opts)
  begin
    res = driver.execute_script(<<~JS)
      const d = new Date("2026-09-12T17:42:00Z");
      const tShort = new Intl.DateTimeFormat(undefined, { timeStyle: "short" }).format(d);
      const tHM = new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(d);
      const dShort = new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(d);
      const dMed = new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(d);
      const dFull = new Intl.DateTimeFormat(undefined, { weekday: "long", month: "long", day: "numeric" }).format(d);
      const dtShort = new Intl.DateTimeFormat(undefined, { dateStyle: "short", timeStyle: "short" }).format(d);
      const dtFull = new Intl.DateTimeFormat(undefined, { dateStyle: "full", timeStyle: "short" }).format(d);
      const rtf = new Intl.RelativeTimeFormat(undefined, { numeric: "auto" });
      return {
        locale: Intl.DateTimeFormat().resolvedOptions().locale,
        tz: Intl.DateTimeFormat().resolvedOptions().timeZone,
        tShort, tShortCodes: [...tShort].map(c => c.charCodeAt(0).toString(16)),
        tHM, tHMCodes: [...tHM].map(c => c.charCodeAt(0).toString(16)),
        dShort, dMed, dFull, dtShort, dtFull,
        rtf_m5: rtf.format(-5, "day"),
        rtf_m1: rtf.format(-1, "day"),
        rtf_0: rtf.format(0, "day"),
        rtf_1: rtf.format(1, "day"),
        rtf_3: rtf.format(3, "day")
      };
    JS
    p res
  ensure
    driver.quit
  end
'

