cat <<'EOF' > app/javascript/helpers/date_helpers.js
const MS_PER_DAY = 1000 * 60 * 60 * 24

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function isSameYear(dateA, dateB) {
  return dateA.getFullYear() === dateB.getFullYear()
}

export function formatTime(date) {
  return normalizeSpaces(formatters().time.format(date))
}

export function formatDate(date) {
  return normalizeSpaces(formatters().date.format(date))
}

export function formatShortDate(date, now = new Date()) {
  const formatter = isSameYear(date, now) ? formatters().shortDate : formatters().date
  return normalizeSpaces(formatter.format(date))
}

export function formatWeekday(date, now = new Date()) {
  const formatter = isSameYear(date, now) ? formatters().weekday : formatters().weekdayWithYear
  return normalizeSpaces(formatter.format(date))
}

export function formatDateTime(date) {
  return normalizeSpaces(formatters().dateTime.format(date))
}

export function formatFullDateTime(date) {
  return normalizeSpaces(formatters().fullDateTime.format(date))
}

export function formatRelativeTime(date, now = new Date()) {
  const daysAgo = signedDifferenceInDays(date, now)

  if (daysAgo === 0) {
    return formatTime(date)
  } else if (daysAgo > -7 && daysAgo < 7) {
    return formatters().relativeDay.format(-daysAgo, "day")
  } else {
    return formatShortDate(date, now)
  }
}

export function formatRelativeDay(date, now = new Date()) {
  const daysAgo = signedDifferenceInDays(date, now)

  if (daysAgo >= -1 && daysAgo <= 1) {
    return formatters().relativeDay.format(-daysAgo, "day")
  } else {
    return formatWeekday(date, now)
  }
}

export function formatInDays(date, now = new Date()) {
  const daysUntil = Math.max(0, signedDifferenceInDays(now, date))
  return formatters().relativeDay.format(daysUntil, "day")
}

let cachedFormatters
let cachedTimeZone

function formatters() {
  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone

  if (!cachedFormatters || cachedTimeZone !== timeZone) {
    cachedTimeZone = timeZone
    cachedFormatters = {
      time: new Intl.DateTimeFormat("en-US", { timeStyle: "short" }),
      date: new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }),
      shortDate: new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }),
      weekday: new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }),
      weekdayWithYear: new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" }),
      dateTime: new Intl.DateTimeFormat("en-US", { dateStyle: "short", timeStyle: "short" }),
      fullDateTime: new Intl.DateTimeFormat("en-US", { dateStyle: "full", timeStyle: "short" }),
      relativeDay: new Intl.RelativeTimeFormat("en", { numeric: "auto" })
    }
  }

  return cachedFormatters
}

function normalizeSpaces(string) {
  return string.replace(/[\u202f\u00a0]/g, " ")
}
